@@ -0,0 +1,37 @@
+import { memoryStore } from "../db/store.js";
+import { AppError } from "../errors.js";
+import { consume } from "./batches.js";
+import { scaled } from "./recipes.js";
+
+/** Books all new sale lines together and saves their ingredient quantities. */
+export function importSaleLines(store, rows) {
+  const imported = new Set(store.data.sales.map((sale) => sale.ticket));
+  const tickets = new Set();
+  let dishes = 0;
+  const staged = memoryStore(store.data);
+  for (const { row, ticket, soldAt, dishId, qty } of rows) {
+    const dish = staged.data.dishes?.find((candidate) => candidate.id === dishId);
+    if (!dish)
+      throw new AppError("bad_request", { reason: `row ${row}: unknown dish ${dishId}` });
+    if (imported.has(ticket)) continue;
+    const recipe = staged.data.recipes.find((candidate) => candidate.id === dish.recipeId);
+    if (!recipe)
+      throw new AppError("bad_request", { reason: `row ${row}: no recipe for dish ${dishId}` });
+    const ingredients = scaled(recipe, qty).filter((ingredient) => ingredient.qty > 0);
+    try {
+      for (const { itemId, qty: used } of ingredients)
+        consume(staged, itemId, used, { at: soldAt, ref: `sale:${ticket}` });
+    } catch (error) {
+      if (error.code === "not_enough_stock")
+        throw new AppError("sale_stock", { ...error.params, row });
+      if (error instanceof AppError)
+        throw new AppError("bad_request", { reason: `row ${row}: invalid recipe ingredients` });
+      throw error;
+    }
+    staged.data.sales.push({ ticket, soldAt, dishId, qty, ingredients });
+    tickets.add(ticket);
+    dishes += qty;
+  }
+  if (tickets.size) store.data = staged.data;
+  return { tickets: tickets.size, dishes };
+}
