diff --git a/src/io/sales-import.js b/src/io/sales-import.js
new file mode 100644
index 0000000..00c67e7
--- /dev/null
+++ b/src/io/sales-import.js
@@ -0,0 +1,44 @@
+// Check the CSV before passing sale lines to the domain.
+import { isDate } from "../dates.js";
+import { AppError } from "../errors.js";
+import { importSaleLines } from "../domain/sales.js";
+import { parseCsv } from "./csv.js";
+
+const HEADER = ["ticket", "soldAt", "dishId", "qty"];
+const CSV_ROW = /^(?:"(?:[^"]|"")*"|[^",]*)(?:,(?:"(?:[^"]|"")*"|[^",]*))*$/;
+const INSTANT = /^\d{4}-\d{2}-\d{2}T(?:[01]\d|2[0-3]):[0-5]\d:[0-5]\d(?:\.\d+)?(?:Z|[+-][01]\d:[0-5]\d)$/;
+
+/** Imports sales from CSV and returns the ticket and dish counts. */
+export function importSales(store, csv) {
+  const lines = csv.split(/\r?\n/);
+  const [header = []] = parseCsv(lines[0]);
+  const fields = header.map((field) => field.trim());
+  if (!CSV_ROW.test(lines[0]) || fields.length !== HEADER.length ||
+      HEADER.some((name) => !fields.includes(name)))
+    throw new AppError("bad_request", { reason: "row 1: expected ticket,soldAt,dishId,qty columns" });
+
+  const rows = [];
+  for (const [index, line] of lines.entries()) {
+    if (index === 0 || !line.trim()) continue;
+    const row = index + 1;
+    if (!CSV_ROW.test(line))
+      throw new AppError("bad_request", { reason: `row ${row}: malformed CSV` });
+    const [values] = parseCsv(line);
+    if (values.length !== HEADER.length)
+      throw new AppError("bad_request", { reason: `row ${row}: expected four fields` });
+    const { ticket, soldAt, dishId, qty } = Object.fromEntries(
+      fields.map((field, i) => [field, values[i].trim()]),
+    );
+    if (!ticket)
+      throw new AppError("bad_request", { reason: `row ${row}: ticket is required` });
+    const instant = new Date(soldAt);
+    if (!INSTANT.test(soldAt) || !Number.isFinite(instant.getTime()) || !isDate(soldAt.slice(0, 10)))
+      throw new AppError("bad_request", { reason: `row ${row}: soldAt must be an ISO instant` });
+    for (const [field, value] of Object.entries({ dishId, qty })) {
+      if (!/^\d+$/.test(value) || !Number.isSafeInteger(Number(value)) || Number(value) < 1)
+        throw new AppError("bad_request", { reason: `row ${row}: ${field} must be a positive whole number` });
+    }
+    rows.push({ row, ticket, soldAt: instant.toISOString(), dishId: Number(dishId), qty: Number(qty) });
+  }
+  return importSaleLines(store, rows);
+}
